def subtract(a, b):
    # Merge overlapping/touching intervals in a list
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [i for i in intervals if i[0] < i[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add new interval
                merged.append([start, end])

        return merged

    # Merge both input lists
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []

            for c_start, c_end in current_ranges:
                # No overlap between [c_start, c_end) and [b_start, b_end)
                if c_end <= b_start or c_start >= b_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap, subtract b from c
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    if c_end > b_end:
                        new_ranges.append([b_end, c_end])

            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort and merge touching intervals
    result.sort()
    if not result:
        return []

    final = [result[0]]
    for start, end in result[1:]:
        if start <= final[-1][1]:
            final[-1][1] = max(final[-1][1], end)
        else:
            final.append([start, end])

    return final

